// One watermark per object, read from hubspot.sync_state() (migration 065 returns a row for
// contacts, companies and deals; migration 062 returned only contacts, so 065 must be applied
// before this workflow runs or the two branches below both start from the epoch every time).
//
// SAME RULES AS THE CONTACTS SYNC, and for the same reasons:
//
//   * THE FLOOR IS THE EPOCH, NOT A RECENT DATE. A recent floor silently skips everything last
//     touched before it, and nothing reports the gap. On the first run the tables are empty, so
//     this pulls full history; after that the watermark takes over and runs are small.
//   * THE WATERMARK IS REWOUND TWO SECONDS, not a minute. The watermark is max(hs_lastmodifieddate)
//     of the rows we STORED — HubSpot timestamps compared against a HubSpot filter — so clock skew
//     between machines never enters into it, and the only real risk is a record sharing the exact
//     millisecond of the last one stored, which GT would skip. Two seconds covers that.
//
//     A MINUTE WAS ACTIVELY DANGEROUS HERE. Every contact in this portal was bulk-modified on
//     2026-09-10 between 04:23 and 12:29, so 1.1M records span eight hours: a 10,000-record page
//     covers about 260 seconds of that range, and rewinding 60 of them threw away a quarter of
//     each run. Compress the same bulk edit into 20 minutes and a page covers ~10 seconds, the
//     rewind exceeds it, and the sync loops forever making negative progress.
const FLOOR = 0;
const REWIND_MS = 2 * 1000;

const state = {};
for (const r of $input.all()) {
  const j = r.json || {};
  if (j.source) state[j.source] = j.newest_modified;
}

// POST {"since":"2026-01-01"} to the webhook to re-read a period on purpose — after a mapping
// change, or to repair a gap — without truncating the tables. The schedule and the manual trigger
// carry no body and ignore it.
let override = null;
try {
  const body = $('Webhook: Sync now').first().json.body || {};
  const t = body.since ? Date.parse(body.since) : NaN;
  if (Number.isFinite(t)) override = t;
} catch (e) { /* not triggered by the webhook */ }

const since = key => {
  if (override !== null) return String(override);
  const v = state[key] ? Date.parse(state[key]) : NaN;
  return String(Number.isFinite(v) ? Math.max(FLOOR, v - REWIND_MS) : FLOOR);
};

return [{ json: { since_deals: since('deals'), since_companies: since('companies') } }];

