// 100 pages x 100 records = 10,000 per execution, which is not our choice: HubSpot's search API
// refuses to page past 10,000 results for ANY one query. The watermark is what gets past it — each
// run starts where the last one stopped, so a backfill completes over several runs rather than one.
// 20,863 deals is ~3 runs. Nothing is lost in between; it is only slow to become complete.
const rows = [];
for (const item of $input.all()) {
  for (const r of (item.json.results || [])) {
    const p = r.properties || {};
    rows.push({
      hs_object_id: Number(r.id),
      dealname: p.dealname || null,
      pipeline: p.pipeline || null,
      dealstage: p.dealstage || null,
      // Empty string is what HubSpot sends for an unset number; Number('') is 0, which would
      // silently invent a zero-value deal.
      amount: (p.amount === '' || p.amount == null) ? null : Number(p.amount),
      closedate: p.closedate || null,
      associated_contact_ids: [],
      associated_company_ids: [],
      hs_lastmodifieddate: p.hs_lastmodifieddate || null,
      synced_at: new Date().toISOString(),
    });
  }
}
// ONE item carrying the whole batch — the upsert takes the array as a single parameter. Nothing
// downstream runs when this is empty, which is the wanted behaviour for "no deals changed".
return rows.length ? [{ json: { rows } }] : [];

// ONE ITEM PER 100 IDS. The v4 batch association endpoint takes at most 100 inputs per call, and an
// n8n HTTP node runs once per input item — so chunking here is what turns 10,000 deals into 100
// association calls without a loop node.
const rows = $input.first().json.rows || [];
const SIZE = 100;
const out = [];
for (let i = 0; i < rows.length; i += SIZE) {
  out.push({ json: { ids: rows.slice(i, i + SIZE).map(r => r.hs_object_id) } });
}
return out;

// Fold both association reads back onto the rows.
//
// BOTH EDGES ARE ARRAYS BECAUSE BOTH GENUINELY FAN OUT — 2,330 contacts in this portal have more
// than one deal (the heaviest has 25) and 1,328 companies have more than one. A scalar "the
// company" or "the deal" would be wrong for thousands of records, and wrong silently.
//
// A deal with no association is left with the empty array the row was built with, not dropped: it
// is a real deal that simply reaches nobody we track, and hiding it would make the mirror disagree
// with HubSpot's own count.
const rows = $('Prepare deal rows').first().json.rows || [];
const byId = new Map(rows.map(r => [String(r.hs_object_id), r]));

// v4 batch read answers { results: [ { from: { id }, to: [ { toObjectId, associationTypes } ] } ] }
const fold = (items, field) => {
  for (const item of items) {
    for (const r of ((item.json || {}).results || [])) {
      const row = byId.get(String(r.from && r.from.id));
      if (!row) continue;
      const ids = (r.to || []).map(t => Number(t.toObjectId)).filter(Number.isFinite);
      // De-duplicated: HubSpot returns one entry per association TYPE, so a contact that is both
      // the primary and a labelled contact on the same deal comes back twice.
      row[field] = [...new Set(row[field].concat(ids))];
    }
  }
};

fold($('HubSpot: Deal → contact associations').all(), 'associated_contact_ids');
fold($input.all(), 'associated_company_ids');

return [{ json: { rows } }];

