// 205,769 companies against HubSpot's hard 10,000-per-query paging ceiling is ~21 runs to backfill.
// See the note on the deals branch: the watermark is what walks past the ceiling.
const rows = [];
for (const item of $input.all()) {
  for (const r of (item.json.results || [])) {
    const p = r.properties || {};
    rows.push({
      hs_object_id: Number(r.id),
      name: p.name || null,
      domain: p.domain || null,
      state: p.state || null,
      lifecyclestage: p.lifecyclestage || null,
      associated_contact_ids: [],
      hs_lastmodifieddate: p.hs_lastmodifieddate || null,
      synced_at: new Date().toISOString(),
    });
  }
}
return rows.length ? [{ json: { rows } }] : [];

const rows = $input.first().json.rows || [];
const SIZE = 100;
const out = [];
for (let i = 0; i < rows.length; i += SIZE) {
  out.push({ json: { ids: rows.slice(i, i + SIZE).map(r => r.hs_object_id) } });
}
return out;

// THIS IS THE EDGE THAT MADE THE WHOLE DESIGN WORTH IT. A contact-to-company link is one fact and
// could be stored on either end; storing it here costs ~2,058 batch calls against ~11,167 on the
// contact side, and it means hubspot.hubspot_contacts needs no migration and the contacts sync that
// is already running is untouched.
//
// The many-to-many is real: contact 53284377 is associated with four companies (NJ Ravens FC, New
// Jersey Santos Rush, Lasker Rink, First Shot Soccer). HubSpot's own `associatedcompanyid` property
// on a contact would have returned exactly one of those four.
const rows = $('Prepare company rows').first().json.rows || [];
const byId = new Map(rows.map(r => [String(r.hs_object_id), r]));

for (const item of $input.all()) {
  for (const r of ((item.json || {}).results || [])) {
    const row = byId.get(String(r.from && r.from.id));
    if (!row) continue;
    const ids = (r.to || []).map(t => Number(t.toObjectId)).filter(Number.isFinite);
    row.associated_contact_ids = [...new Set(row.associated_contact_ids.concat(ids))];
  }
}

return [{ json: { rows } }];

// The pipeline/stage map, flattened. GET /crm/v3/pipelines/deals returns every pipeline with its
// stages nested; a deal row stores only the stage id, so this is what turns "1607069" into
// "Closed". Four pipelines, 76 stages in this portal — small enough to replace wholesale.
//
// WON AND LOST ARE HUBSPOT OWN FLAGS, not a reading of the label. In this portal the stage whose
// id is literally "closedlost" is labelled "Initial Interest" and is OPEN at probability 0.5 —
// any heuristic on the id or the text gets that exactly backwards.
const rows = [];
for (const item of $input.all()) {
  for (const p of ((item.json || {}).results || [])) {
    for (const s of (p.stages || [])) {
      const m = s.metadata || {};
      rows.push({
        stage_id: String(s.id),
        pipeline_id: String(p.id),
        pipeline_label: p.label || null,
        stage_label: s.label || null,
        display_order: Number.isFinite(Number(s.displayOrder)) ? Number(s.displayOrder) : null,
        is_closed: String(m.isClosed) === 'true',
        // Empty string and undefined both mean "not set"; Number() would turn them into 0, which
        // is the value that means LOST.
        probability: (m.probability === undefined || m.probability === null || m.probability === '')
          ? null : Number(m.probability),
        synced_at: new Date().toISOString(),
      });
    }
  }
}
return rows.length ? [{ json: { stages: rows } }] : [];
